/**
 * Rx Detective side-effect mysteries, hand-written and checked one by one.
 * Each names the action that explains the picture; the three wrong actions
 * were picked so none of them also explains it for this medicine.
 * Types only come from content.ts, so there is no import loop at runtime.
 */
import { PHARM_EXAMS, type ItemTags, type Level } from "../item-tags";
import type { Mystery } from "./content";
import { drugById } from "./drugs";

const tag = (topic: string, level: Level, objective: string, learn: string): ItemTags => ({ topic, level, objective, exams: PHARM_EXAMS, learn });

/** Tags, wrong-option notes and fixed wrong outcomes for the first mysteries and puzzles. */
export const BASE_TAGS: Record<string, { not: string; tags: ItemTags; options?: string[] }> = {
  "olz-weight": { not: "Prolactin-pathway D2 block raises prolactin, not appetite. Alpha-1 block drops blood pressure on standing. Gut 5-HT3 stimulation causes nausea, and olanzapine does not raise serotonin anyway.", tags: tag("Olanzapine: weight gain", 2, "Link sedation and hunger on olanzapine to histamine H1 block.", "antipsychotics") },
  "que-dizzy": { not: "H1 block makes her sleepy but does not drop blood pressure on standing. Muscarinic block dries the mouth and can confuse. Movement-pathway D2 block causes stiffness, which quetiapine rarely does.", tags: tag("Quetiapine: falls on standing", 2, "Explain dizziness and falls on standing by alpha-1 block.", "antipsychotics") },
  "ami-dry": { not: "Alpha-1 block causes dizziness on standing, not dryness. H1 block sedates and adds appetite. Extra serotonin at 5-HT2 receptors affects sexual function and sleep; none of these dries the mouth, slows the gut and holds the bladder.", tags: tag("Tricyclics: anticholinergic effects", 1, "Recognise the dry, constipated, blurred, retained picture of muscarinic block.", "antidepressants") },
  "hal-stiff": { not: "Prolactin-pathway D2 block affects periods and breasts, not muscles. Muscarinic block eases this stiffness, which is why anticholinergics are the antidote. H1 block sedates but does not stiffen.", tags: tag("Haloperidol: parkinsonism", 1, "Recognise drug-induced parkinsonism as D2 block in the movement pathway.", "antipsychotics") },
  "ris-prl": { not: "Movement-pathway D2 block causes stiffness and tremor, not milk. Prolactin is held down by dopamine, not by 5-HT2 receptors, and risperidone blocks 5-HT2A anyway. H1 block sedates and adds appetite.", tags: tag("Risperidone: raised prolactin", 2, "Explain missed periods and milk on risperidone by D2 block in the prolactin pathway.", "antipsychotics") },
  "ari-prl": { not: "Full D2 block in the prolactin pathway is what risperidone did, and it raises prolactin rather than bringing it back to normal. H1 and alpha-1 block cause sleepiness and dizziness and play no part in prolactin.", tags: tag("Aripiprazole: prolactin back to normal", 4, "Tell full D2 block from D2 partial agonism by what each does to prolactin.", "antipsychotics") },
  "mir-sleep": { not: "Mirtazapine barely blocks alpha-1 or muscarinic receptors, so neither explains sound sleep and hunger. Gut 5-HT3 stimulation would cause nausea; mirtazapine blocks 5-HT3 instead.", tags: tag("Mirtazapine: sleep and appetite", 2, "Use mirtazapine's H1 block as a benefit in insomnia and weight loss.", "antidepressants") },
  "ser-nausea": { not: "Sertraline hardly touches H1, muscarinic or movement-pathway D2 receptors. None of those causes early nausea that fades as receptors adapt.", tags: tag("SSRIs: early nausea", 1, "Recognise early, fading nausea on an SSRI as gut serotonin at 5-HT3.", "antidepressants") },
  "esc-sex": { not: "Gut 5-HT3 stimulation explains nausea, not sexual effects. Escitalopram has almost no alpha-1 or muscarinic block, so those cannot explain it.", tags: tag("SSRIs: sexual side effects", 2, "Explain low desire and delayed orgasm on an SSRI by serotonin at 5-HT2.", "antidepressants") },
  "ami-od": { not: "Muscarinic block explains the wide pupils and fast heart, but not the wide QRS and the fit. Alpha-1 block lowers blood pressure and H1 block causes drowsiness; neither widens the QRS.", tags: tag("Tricyclic overdose", 4, "Recognise a wide QRS in tricyclic overdose as heart sodium channel block and refer as an emergency.", "antidepressants") },
  "mph-appetite": { not: "Methylphenidate does not block H1 or muscarinic receptors or raise gut serotonin. H1 block would increase appetite and cause sleepiness, the opposite of this picture.", tags: tag("Stimulants: appetite and sleep", 2, "Link poor appetite and late sleep on methylphenidate to more dopamine and noradrenaline.", "child") },
  "don-faint": { not: "Donepezil has no alpha-1, heart sodium channel or H1 action. Those would cause dizziness on standing, conduction problems or sleepiness, not a slow pulse from extra acetylcholine.", tags: tag("Donepezil: slow pulse", 3, "Explain a slow pulse and fainting on donepezil by extra acetylcholine at the heart.", "neurocognitive") },
  "ser-tram": { options: ["reaction", "kidney", "breath"], not: "The flushing and vomiting reaction belongs to disulfiram with alcohol. Neither medicine depends on the kidneys in a way the other changes. Sedation and slow breathing are the opposite of this hot, jerky, agitated picture.", tags: tag("Serotonin syndrome: SSRI with tramadol", 2, "Recognise serotonin syndrome when tramadol is added to an SSRI.", "antidepressants") },
  "esc-line": { options: ["reaction", "kidney", "down"], not: "There is no alcohol, so no flushing reaction. Neither drug changes how the kidneys clear the other. Linezolid does not speed up the liver, so escitalopram's level does not fall.", tags: tag("Serotonin syndrome: linezolid", 3, "Recall that linezolid is a weak MAO inhibitor and adds to SSRI serotonin.", "antidepressants") },
  "flu-ris": { options: ["down", "ss", "kidney"], not: "Fluoxetine slows the liver here, so the level rises rather than falls. Risperidone adds no serotonin, so there is no serotonin overload. Risperidone's rise comes from the liver, not the kidneys.", tags: tag("CYP2D6: fluoxetine with risperidone", 3, "Predict a higher risperidone level when a CYP2D6 blocker is added.", "antipsychotics") },
  "flv-clz": { options: ["down", "kidney", "reaction"], not: "Fluvoxamine blocks the enzyme, so clozapine rises rather than falls. Clozapine is cleared by the liver, not mainly the kidneys. There is no alcohol, so no flushing reaction.", tags: tag("CYP1A2: fluvoxamine with clozapine", 3, "Recall that fluvoxamine strongly blocks CYP1A2 and raises clozapine.", "antipsychotics") },
  "clz-smoke": { options: ["down", "kidney", "ss"], not: "Levels fall when someone starts smoking; he stopped, so they rise. The kidneys are not the route here. Clozapine is not a serotonin booster, so serotonin syndrome does not fit.", tags: tag("Clozapine and stopping smoking", 4, "Predict a rising clozapine level when a smoker quits.", "antipsychotics") },
  "cbz-pill": { options: ["up", "kidney", "ss"], not: "Carbamazepine speeds the liver up, so hormone levels fall, not rise. The hormones are cleared by the liver, not the kidneys. Neither raises serotonin.", tags: tag("Carbamazepine and contraception", 3, "Recall that carbamazepine makes the combined pill fail.", "stabilisers") },
  "li-ibu": { options: ["up", "down", "reaction"], not: "Lithium is not broken down by the liver at all, so liver options do not apply. There is no alcohol and no disulfiram, so no flushing reaction.", tags: tag("Lithium with anti-inflammatory painkillers", 2, "Recall that NSAIDs raise lithium by cutting kidney clearance.", "stabilisers") },
  "li-dehyd": { options: ["up", "ss", "breath"], not: "The liver plays no part in lithium clearance. Lithium does not cause serotonin syndrome here, and nothing in this story slows breathing.", tags: tag("Lithium and dehydration", 3, "Predict lithium toxicity when salt and water are lost.", "stabilisers") },
  "vpa-ltg": { options: ["down", "kidney", "ss"], not: "Valproate slows lamotrigine's clearance, so the level rises. The kidneys are not the main route for lamotrigine. Neither drug raises serotonin.", tags: tag("Valproate with lamotrigine", 4, "Recall that valproate doubles lamotrigine and why the dose is halved.", "stabilisers") },
  "lor-alc": { options: ["ss", "qt", "reaction"], not: "Neither raises serotonin. The danger here is sedation, not the heart rhythm. The flushing reaction is disulfiram with alcohol, not a benzodiazepine.", tags: tag("Benzodiazepines with alcohol", 1, "Recognise slowed breathing when two sedatives add up.", "anxiety") },
  "dis-alc": { options: ["breath", "ss", "kidney"], not: "This is a hot, flushed, racing reaction, not sedation. There is no serotonin booster. The kidneys are not involved; acetaldehyde piles up because an enzyme is blocked.", tags: tag("Disulfiram and hidden alcohol", 2, "Recognise the disulfiram reaction from hidden alcohol.", "substance") },
  "hal-azi": { options: ["ss", "kidney", "reaction"], not: "Neither raises serotonin. Neither changes kidney clearance of the other. There is no alcohol, so no flushing reaction.", tags: tag("QT: haloperidol with azithromycin", 3, "Spot two QT-lengthening medicines and ask for an ECG first.", "antipsychotics") },
  "cit-meth": { options: ["reaction", "kidney", "down"], not: "There is no alcohol, so no flushing reaction. The kidneys are not the issue. Neither medicine speeds up the liver.", tags: tag("QT: methadone with citalopram", 3, "Choose a lower-QT antidepressant for someone on methadone.", "antidepressants") },
  "ser-para": { options: ["bleed", "kidney", "ss"], not: "Paracetamol does not stop platelets working, unlike anti-inflammatories, so bleeding is not raised. It does not change kidney clearance of sertraline, and adds no serotonin.", tags: tag("SSRIs and safe painkillers", 1, "Recall paracetamol as the safer painkiller alongside an SSRI.", "antidepressants") },
};

type Wrong = [string, string, string];

function M(id: string, drug: string, who: string, story: string, clues: string[], answer: string, wrong: Wrong, why: string, not: string, level: Level, objective: string): Mystery {
  const d = drugById(drug);
  if (!d) throw new Error(`Rx mystery ${id}: unknown medicine ${drug}`);
  return { id, drug, who, story, clues, answer, options: [answer, ...wrong], why, not, topic: d.topic, tags: tag(`${d.name}: ${clues[0].toLowerCase()}`, level, objective, d.topic) };
}

export const MORE_MYSTERIES: Mystery[] = [
  /* ------------------------------------------------ antidepressants */
  M("ser-bleed", "sertraline", "Mrs Mathur, 68, Jaipur", "On sertraline for a year and aspirin since her heart attack. She shows you purple bruises on both arms and says her gums bleed when she brushes.", ["Bruises", "Bleeding gums", "Also on aspirin"], "sertplt", ["5ht3", "a1", "m1"], "Platelets cannot make serotonin; they soak it up from the blood through the same serotonin pump an SSRI blocks. Emptied of serotonin, they clump less well, so bleeding rises, more so with aspirin or anti-inflammatories.", "Gut 5-HT3 stimulation explains early nausea. Alpha-1 block causes dizziness on standing. Muscarinic block dries the mouth. None of them changes how blood clots.", 3, "Explain SSRI bleeding through the platelet serotonin pump."),
  M("esc-na", "escitalopram", "Mr Iyer, 78, Chennai", "Started escitalopram for low mood. He also takes a water tablet for blood pressure. His daughter says he is muddled and unsteady. His sodium is 124.", ["Older adult", "Water tablet", "Low sodium", "Confused"], "adh", ["v2block", "h1", "sertplt"], "SSRIs can raise the water-holding hormone (ADH). The kidneys keep back water, the blood is diluted and sodium falls. Older age, low body weight and water tablets add to the risk, so sodium is checked in the first month.", "A kidney deaf to the water-holding hormone is lithium's effect: it loses water, which pushes sodium up, the opposite. H1 block causes drowsiness, not low sodium. The platelet pump explains bruising.", 4, "Tell SSRI low sodium (too much ADH effect) from lithium's water loss."),
  M("flu-insomnia", "fluoxetine", "Tanvi, 20, Pune", "Fluoxetine in the morning for depression. She feels wired, a little jittery, and cannot fall asleep before 2 am.", ["Jittery", "Can't sleep", "Activating medicine"], "5ht2", ["h1", "m1", "5ht3block"], "Extra serotonin stimulating 5-HT2A and 5-HT2C receptors can feel activating early on: restlessness and broken sleep. Fluoxetine is among the more activating SSRIs, so it is taken in the morning.", "H1 block would make her sleepy, the opposite. Fluoxetine has almost no muscarinic block, which would dry the mouth anyway. Fluoxetine does not block 5-HT3; that is a mirtazapine trait that eases sickness.", 2, "Link insomnia and jitteriness on fluoxetine to extra serotonin at 5-HT2."),
  M("par-dry", "paroxetine", "Mr Dsouza, 55, Mangaluru", "Switched from escitalopram to paroxetine for panic. Now his mouth is dry, he is constipated and reading the newspaper is blurry.", ["Dry mouth", "Constipated", "Blurred reading"], "m1", ["5ht3", "sertplt", "a2block"], "Paroxetine is the SSRI with the most muscarinic block. That is why it, unlike escitalopram, can dry the mouth, slow the gut and blur near vision, much like a mild tricyclic.", "Gut 5-HT3 stimulation causes nausea, not dryness. The platelet pump explains bruising. Alpha-2 brake block is how mirtazapine works; paroxetine does not do it.", 4, "Tell paroxetine apart from other SSRIs by its muscarinic block."),
  M("ven-bp", "venlafaxine", "Mrs Banerjee, 49, Kolkata", "Venlafaxine went up to 225 mg because her depression had only partly lifted. At her review her blood pressure is 156/98, higher than ever before.", ["Higher dose", "Blood pressure up", "SNRI"], "ne", ["a1", "h1", "5ht3"], "At lower doses venlafaxine acts mostly on the serotonin pump. At higher doses it also blocks the noradrenaline pump, and the extra noradrenaline tightens blood vessels, so blood pressure rises with dose.", "Alpha-1 block lowers blood pressure, the opposite. H1 block sedates. Gut 5-HT3 stimulation causes nausea. None of them pushes blood pressure up.", 3, "Explain dose-related high blood pressure on venlafaxine by extra noradrenaline."),
  M("dul-urine", "duloxetine", "Mr Chopra, 62, Amritsar", "Duloxetine for depression and diabetic nerve pain. He now waits a long time to start passing urine, and his pulse is 98.", ["Slow to pass urine", "Pulse up", "Pain medicine too"], "ne", ["m1", "h1", "5ht2c"], "Extra noradrenaline tightens the muscle at the bladder outlet and speeds the heart. Duloxetine blocks the noradrenaline pump, so urinary hesitancy and a faster pulse can follow, especially in older men.", "Muscarinic block can also hold urine, but duloxetine barely blocks muscarinic receptors; here the outlet is squeezed shut by noradrenaline. H1 block sedates. 5-HT2C block adds appetite. Neither tightens the bladder outlet.", 4, "Tell noradrenaline-driven urinary hesitancy from muscarinic retention."),
  M("dvl-pulse", "desvenlafaxine", "Ms Kaur, 34, Ludhiana", "Two months on desvenlafaxine. Her depression is lifting, but she feels her heart thumping at rest and sweats more.", ["Palpitations", "Sweating", "SNRI"], "ne", ["ach", "nach", "h1"], "Desvenlafaxine blocks both the serotonin and the noradrenaline pump. More noradrenaline at the heart and sweat glands brings a faster pulse, palpitations and sweating.", "Extra acetylcholine at the heart slows the pulse, the opposite. Heart sodium channel block is a tricyclic overdose problem. H1 block sedates.", 2, "Recognise noradrenaline effects on the heart with an SNRI."),
  M("esc-qt", "escitalopram", "Mr Rao, 81, Visakhapatnam", "On escitalopram 20 mg. After a bout of diarrhoea his potassium is low. A routine ECG shows the QT interval stretched to 490 ms.", ["Long QT", "Low potassium", "Higher dose"], "herg", ["nach", "ach", "a1"], "Many medicines slow the heart's recovery after each beat by blocking hERG potassium channels. That lengthens QT, and low potassium makes it worse. Citalopram and escitalopram do this in a dose-related way, so older adults get lower doses.", "Heart sodium channel block widens the QRS, as in tricyclic overdose, rather than stretching QT. Extra acetylcholine slows the pulse. Escitalopram has no real alpha-1 block, which would lower blood pressure.", 4, "Tell QT lengthening (potassium channel) from QRS widening (sodium channel)."),
  M("cmi-orgasm", "clomipramine", "Mr Joseph, 29, Kottayam", "Clomipramine has eased his washing rituals a lot, but he can barely reach orgasm and is worried about his marriage.", ["Delayed orgasm", "OCD better", "Strong serotonin pump block"], "5ht2", ["h1", "nach", "mt1"], "Clomipramine is the most serotonergic tricyclic, which is why it helps OCD. The same extra serotonin at 5-HT2 receptors damps sexual response, especially orgasm.", "H1 block causes sleepiness and appetite, not orgasm problems. Heart sodium channel block matters in overdose. Clomipramine has no melatonin action.", 3, "Link clomipramine's sexual effects to its strong serotonin action."),
  M("imi-ortho", "imipramine", "Mr Ghosh, 70, Howrah", "Imipramine for long-standing depression. He nearly fell getting out of bed and says the room goes grey when he stands.", ["Dizzy on standing", "Older adult", "Tricyclic"], "a1", ["5ht3", "dane", "mt1"], "Tricyclics block alpha-1 receptors that keep blood vessels tight. On standing, blood pools in the legs, pressure drops and the brain is briefly short of blood. Getting up slowly helps.", "Gut 5-HT3 stimulation explains nausea. More dopamine and noradrenaline is a stimulant action. Imipramine has no melatonin action. None of them drops blood pressure on standing.", 2, "Recognise postural dizziness on a tricyclic as alpha-1 block."),
  M("ami-hangover", "amitriptyline", "Ms Fernandes, 38, Panaji", "Amitriptyline 10 mg at night to prevent migraine. Her headaches are fewer, but she feels heavy and slow until mid-morning.", ["Morning grogginess", "Low dose", "Taken at night"], "h1", ["5ht3", "dane", "d2part"], "Amitriptyline blocks histamine H1 strongly, even at 10 mg. Histamine keeps the brain awake, so blocking it sedates, and the effect can carry into the morning.", "Gut 5-HT3 stimulation causes nausea. More dopamine and noradrenaline would wake her up. D2 partial agonism belongs to aripiprazole. None of them causes a heavy morning.", 1, "Recognise sedation on low-dose amitriptyline as H1 block."),
  M("ami-delirium", "amitriptyline", "Mr Pillai, 82, Thrissur", "Given amitriptyline for nerve pain after shingles. Two days later he is confused at night, picks at the bedsheet and has not passed urine since morning.", ["Confused", "Urine held", "Very old"], "m1", ["5ht3", "mt1", "d2part"], "Acetylcholine is vital for attention and memory, and the ageing brain has less to spare. Muscarinic block can tip an older person into delirium, and the same block holds urine. Strongly anticholinergic medicines are best avoided in the very old.", "Gut 5-HT3 stimulation explains nausea. Amitriptyline has no melatonin action. D2 partial agonism is aripiprazole's action. None explains confusion with urinary retention.", 3, "Recognise anticholinergic delirium in an older adult."),
  M("trz-priapism", "trazodone", "Mr Saxena, 44, Lucknow", "Trazodone 100 mg at night for poor sleep. He comes to emergency at 6 am with a painful erection that has lasted four hours.", ["Painful erection", "Hours long", "Night-time medicine"], "a1", ["5ht2", "dane", "m1"], "Trazodone blocks alpha-1 receptors. In the penis, noradrenaline at alpha-1 is what ends an erection, so blocking it can trap blood. Priapism is a rare emergency; it needs urgent care to protect the tissue.", "Trazodone blocks 5-HT2 receptors rather than flooding them with serotonin. It does not raise dopamine and noradrenaline, and its muscarinic block is negligible.", 4, "Explain trazodone priapism by alpha-1 block and refer it as an emergency."),
  M("trz-sleep", "trazodone", "Mrs Qureshi, 59, Bhopal", "Trazodone 50 mg at bedtime. For the first time in months she falls asleep within half an hour.", ["Sleeps well", "Low dose", "Bedtime"], "h1", ["dane", "5ht3", "ne"], "At low doses trazodone mostly blocks histamine H1, alpha-1 and 5-HT2A receptors, and the H1 block is a main reason it is sleep-inducing. Its serotonin pump block needs higher doses.", "More dopamine and noradrenaline would keep her up. Gut 5-HT3 stimulation causes nausea. More noradrenaline at the heart and vessels is an SNRI effect and would make her alert.", 2, "Explain low-dose trazodone's sleep effect by H1 block."),
  M("mir-weight", "mirtazapine", "Mr Kulkarni, 47, Nashik", "Mood much better on mirtazapine, but he has gained six kilograms and craves sweets in the evening.", ["Weight gain", "Sweet cravings", "Evening hunger"], "5ht2c", ["dane", "sertplt", "d2part"], "Serotonin at 5-HT2C receptors in the hypothalamus acts as an appetite brake. Mirtazapine blocks 5-HT2C, so the brake comes off. Its H1 block adds to the hunger.", "More dopamine and noradrenaline curbs appetite, the opposite. The platelet pump explains bruising. D2 partial agonism belongs to aripiprazole.", 3, "Explain mirtazapine weight gain by 5-HT2C block."),
  M("mir-nonausea", "mirtazapine", "Ms Reddy, 31, Warangal", "Sertraline made her sick every morning, so she switched to mirtazapine. Now the nausea is gone and her sex life is back to normal.", ["No nausea", "No sexual side effects", "Switched from an SSRI"], "5ht3block", ["5ht3", "sertplt", "d2ti"], "Mirtazapine blocks 5-HT3 receptors (and 5-HT2), so the extra serotonin it releases cannot cause sickness or the usual sexual effects. That is why it suits people who could not take an SSRI.", "Stimulating 5-HT3 causes nausea, the very thing that went away. The platelet pump belongs to SSRIs. Prolactin-pathway D2 block raises prolactin and would harm sexual function.", 4, "Tell 5-HT3 stimulation (nausea) from 5-HT3 block (no nausea)."),
  M("mir-mech", "mirtazapine", "A pharmacology tutorial, Delhi", "Your tutor says mirtazapine lifts mood without blocking the serotonin pump at all. It raises serotonin and noradrenaline release instead.", ["No pump block", "More release", "Mood lifts"], "a2block", ["sertplt", "5ht1a", "mt1"], "Alpha-2 receptors on nerve endings act as a brake: when noradrenaline hits them, release slows. Mirtazapine blocks this brake, so more noradrenaline is released, and noradrenaline in turn drives more serotonin release.", "Blocking the serotonin pump is the SSRI action, which mirtazapine does not have. Serotonin 1A partial agonism is buspirone's action. Melatonin receptor stimulation is agomelatine's.", 2, "Recall that mirtazapine works by alpha-2 brake block."),
  M("mir-dose", "mirtazapine", "Dr Batra's ward round, Chandigarh", "A resident asks why the patient on mirtazapine 15 mg is sleepier than the one on 45 mg.", ["Low dose sleepier", "Higher dose less sedating"], "h1", ["5ht3", "sertplt", "gaba"], "H1 block is strong even at low doses and dominates there. At higher doses the extra noradrenaline from alpha-2 block starts to balance the sedation, so 15 mg can be more sedating than 45 mg.", "Gut 5-HT3 stimulation causes nausea, which mirtazapine blocks. The platelet pump is an SSRI action. Mirtazapine does not act on GABA-A receptors.", 4, "Explain why low-dose mirtazapine is more sedating than high-dose."),
  M("bup-sex", "bupropion", "Mr Menon, 41, Kochi", "SSRIs ruined his sex life. On bupropion his mood is better, desire is normal, he eats less and sleeps lightly.", ["Sexual function normal", "Less appetite", "Lighter sleep"], "dane", ["5ht2", "h1", "5ht2c"], "Bupropion blocks the dopamine and noradrenaline pumps and does not touch serotonin. Without extra serotonin there are few sexual effects; the extra dopamine and noradrenaline curb appetite and lighten sleep.", "Extra serotonin at 5-HT2 is what causes SSRI sexual problems, and bupropion does not raise serotonin. H1 block and 5-HT2C block both increase appetite and sleepiness, the opposite.", 3, "Explain why bupropion spares sexual function."),
  M("agm-sleep", "agomelatine", "Ms Bose, 36, Durgapur", "Depressed and waking at 4 am for months. On agomelatine at bedtime, her sleep shifts back to a normal pattern with no morning hangover.", ["Sleep timing restored", "No hangover", "Bedtime dose"], "mt1", ["h1", "gaba", "a1"], "Agomelatine stimulates melatonin receptors (and blocks 5-HT2C), which resets the body clock rather than knocking the brain out. Sleep timing improves without the heavy morning that sedating medicines bring.", "H1 block sedates and often leaves a hangover. Agomelatine has no GABA-A action. Alpha-1 block causes dizziness on standing.", 3, "Explain agomelatine's sleep benefit by melatonin receptor stimulation."),
  M("ser-panic", "sertraline", "Ms Wadhwa, 27, Gurugram", "Started sertraline 50 mg for panic disorder. For the first few days her panic attacks are worse and she feels on edge.", ["Panic worse", "First days", "Full starting dose"], "5ht2", ["h1", "gaba", "beta"], "Early on, extra serotonin stimulates 5-HT2 receptors before they adapt, which can feel like more anxiety. People with panic are sensitive to this, so they start at half the usual dose and go up slowly.", "H1 block would calm and sedate. Sertraline does not act at GABA-A receptors, which would also calm. Beta block slows the heart and eases shaking, the opposite.", 3, "Explain early worsening of panic on an SSRI and why the dose starts low."),
  M("ser-pe", "sertraline", "Mr Arora, 33, Delhi", "Sertraline for depression. He mentions, a little embarrassed, that his long-standing premature ejaculation has stopped being a problem.", ["Ejaculation delayed", "Unexpected benefit"], "5ht2", ["h1", "a1", "mupart"], "Extra serotonin at 5-HT2 receptors in the spinal cord delays ejaculation. In depression this is a side effect, but it is the basis for using SSRIs in premature ejaculation.", "H1 block sedates. Sertraline barely blocks alpha-1. Mu opioid partial agonism belongs to buprenorphine.", 4, "Recognise an SSRI side effect used as a treatment."),
  M("imi-enuresis", "imipramine", "Ishaan, 9, Indore", "After other steps failed, imipramine at night was tried for bedwetting. His mother says he is now dry most nights.", ["Fewer wet nights", "Child", "Night dose"], "m1", ["d2ti", "gaba", "mt1"], "Imipramine's muscarinic block relaxes the bladder wall and tightens control, one reason it reduces bedwetting. It is a second-line choice: alarms and desmopressin come first, and tricyclics are dangerous in overdose.", "Prolactin-pathway D2 block affects hormones, not the bladder. Imipramine does not act at GABA-A or melatonin receptors.", 4, "Link imipramine's bedwetting benefit to its muscarinic block."),
  M("ami-weight", "amitriptyline", "Mrs Shah, 52, Ahmedabad", "Amitriptyline for fibromyalgia. She has gained weight and snacks late at night.", ["Weight gain", "Night snacking"], "h1", ["d2part", "sertplt", "mublock"], "H1 block in the hypothalamus drives appetite as well as sleep. Amitriptyline is one of the strongest H1 blockers among antidepressants, so weight gain is common.", "D2 partial agonism is aripiprazole's action. The platelet pump explains bruising. Opioid receptor block is naltrexone's action.", 2, "Link amitriptyline weight gain to H1 block."),

  /* ------------------------------------------------- antipsychotics */
  M("hal-dyst", "haloperidol", "Sahil, 19, Rohtak", "Hours after his first haloperidol injection in emergency, his eyes roll upwards and his neck twists painfully to one side.", ["Eyes roll up", "Neck twisted", "Young man", "First dose"], "d2ns", ["d2ti", "h1", "5ht2"], "Sudden strong D2 block in the movement pathway can cause acute dystonia: painful muscle spasms of the eyes, neck or tongue. Young men on high-potency drugs are most at risk. An anticholinergic injection relieves it within minutes.", "Prolactin-pathway D2 block affects hormones, not muscles. H1 block sedates. Haloperidol has little action at 5-HT2 and serotonin is not the cause.", 2, "Recognise acute dystonia and its cause."),
  M("hal-td", "haloperidol", "Mr Yadav, 64, Patna", "Twenty years on haloperidol depot. His lips smack and his tongue writhes, worse when he is distracted. The movements began slowly.", ["Lip smacking", "Tongue writhing", "Many years of treatment"], "d2up", ["d2ns", "m1", "h1"], "After years of block, D2 receptors in the movement pathway multiply and become oversensitive. The leading explanation for tardive dyskinesia is this supersensitivity. It is late, often lasting, and anticholinergics can make it worse.", "Acute D2 block causes stiffness and tremor that come early; this is a slow, late picture. Muscarinic block does not cause writhing and can worsen it. H1 block sedates.", 4, "Tell tardive dyskinesia (receptor supersensitivity) from early parkinsonism."),
  M("hal-iv-qt", "haloperidol", "ICU, AIIMS Delhi", "A delirious man after heart surgery is given repeated intravenous haloperidol. His QTc climbs to 520 ms on the monitor.", ["Long QT", "Intravenous", "Heart patient"], "herg", ["nach", "a1", "ach"], "Haloperidol blocks hERG potassium channels, delaying the heart's recovery. The risk is highest given into a vein, at higher doses and in people with heart disease or low potassium or magnesium. ECG monitoring is needed.", "Heart sodium channel block widens the QRS, a tricyclic overdose sign. Haloperidol has little alpha-1 block. Extra acetylcholine slows the pulse; it does not stretch QT.", 4, "Explain QT risk with intravenous haloperidol."),
  M("hal-sick", "haloperidol", "Palliative care unit, Mumbai", "A woman with advanced bowel cancer has constant nausea. A small dose of haloperidol settles it within a day.", ["Nausea eased", "Small dose", "Palliative care"], "d2ctz", ["5ht3", "h1", "m1"], "The vomiting trigger zone in the brainstem is driven by dopamine at D2 receptors. Haloperidol blocks them, which is why low doses are used for nausea caused by chemicals or medicines.", "Stimulating 5-HT3 causes nausea rather than easing it. Haloperidol has very little H1 or muscarinic block, the actions behind cyclizine-type anti-sickness medicines.", 3, "Explain haloperidol's anti-sickness use by D2 block in the vomiting centre."),
  M("hal-lewy", "haloperidol", "Mr Murthy, 76, Mysuru", "He has fluctuating confusion, sees children in the garden and has a slight tremor. One small dose of haloperidol leaves him rigid, falling and much more confused.", ["Very rigid", "Visual hallucinations", "Fluctuating confusion"], "d2ns", ["a1", "h1", "m1"], "This picture suggests dementia with Lewy bodies, where dopamine in the movement pathway is already low. Even a small D2 block can cause severe, sometimes life-threatening, stiffness. Antipsychotics are avoided or used with great care.", "Haloperidol has little alpha-1, H1 or muscarinic action, so none of these explains severe rigidity after one small dose.", 5, "Recognise severe antipsychotic sensitivity in Lewy body dementia."),
  M("cpz-faint", "chlorpromazine", "Mr Das, 45, Cuttack", "His first dose of chlorpromazine was 100 mg. An hour later he fainted on the way to the toilet.", ["Fainted", "First dose", "On standing"], "a1", ["d2part", "5ht3", "dane"], "Chlorpromazine is a strong alpha-1 blocker. Large first doses drop blood pressure on standing, so it is started low and raised slowly.", "D2 partial agonism belongs to aripiprazole. Gut 5-HT3 stimulation causes nausea. More dopamine and noradrenaline would raise blood pressure.", 2, "Recognise first-dose fainting on chlorpromazine as alpha-1 block."),
  M("cpz-dry", "chlorpromazine", "Mrs Lal, 50, Kanpur", "On chlorpromazine for many years. She keeps a water bottle with her for her dry mouth and needs laxatives.", ["Dry mouth", "Constipation", "Low-potency antipsychotic"], "m1", ["d2part", "5ht3", "sertplt"], "Low-potency first-generation antipsychotics like chlorpromazine block muscarinic receptors strongly, so dryness and constipation are common, while stiffness is less common than with haloperidol.", "D2 partial agonism belongs to aripiprazole. Gut 5-HT3 stimulation causes nausea. The platelet pump explains bruising.", 1, "Recognise chlorpromazine's anticholinergic effects."),
  M("tfp-restless", "trifluoperazine", "Mr Khan, 37, Aligarh", "Started trifluoperazine. He cannot sit through the interview: he crosses and uncrosses his legs, gets up and paces. 'My legs won't let me sit.'", ["Can't sit still", "Inner restlessness", "High-potency drug"], "d2ns", ["h1", "5ht2c", "ne"], "Akathisia, an intense inner urge to move, is one of the movement effects of D2 block, commonest with high-potency drugs. It is often missed or mistaken for agitation, and it raises suicide risk if ignored.", "H1 block sedates rather than drives movement. 5-HT2C block adds appetite. Trifluoperazine does not boost noradrenaline at the heart and vessels.", 3, "Recognise akathisia as a D2 movement effect."),
  M("tfp-combo", "trifluoperazine", "OPD pharmacy, Varanasi", "His prescription reads Trinicalm Plus: trifluoperazine with trihexyphenidyl in one tablet. He asks why there are two medicines.", ["Combination tablet", "Stiffness prevented"], "m1", ["h1", "a1", "5ht2c"], "Trifluoperazine's D2 block can cause stiffness and tremor. In the movement pathway dopamine and acetylcholine balance each other, so muscarinic block from trihexyphenidyl restores the balance. Routine combining is debated, because the anticholinergic adds its own harms.", "H1 block sedates and alpha-1 block lowers blood pressure; neither prevents stiffness. 5-HT2C block adds appetite.", 3, "Explain why some Indian antipsychotic brands include trihexyphenidyl."),
  M("flx-breast", "flupentixol", "Mr Gill, 42, Jalandhar", "On flupentixol depot. He has lost sexual desire and his chest has swollen a little on both sides.", ["Breast swelling", "Low desire", "Man"], "d2ti", ["d2ns", "a2block", "mt1"], "Blocking D2 in the prolactin pathway lets prolactin rise. In men this lowers desire and can cause breast swelling.", "Movement-pathway D2 block causes stiffness and tremor, not breast changes. Alpha-2 brake block is mirtazapine's action. Melatonin receptor stimulation is agomelatine's.", 2, "Recognise raised prolactin in a man on a depot."),
  M("ris-faint", "risperidone", "Mrs Chatterjee, 72, Siliguri", "The ward started risperidone 2 mg at once for agitation. She became dizzy and pale every time she stood that first day.", ["Dizzy on standing", "Full dose at once", "Older adult"], "a1", ["d2ti", "5ht3", "dane"], "Risperidone is a strong alpha-1 blocker. That is why it is started low and increased in steps, especially in older people, to avoid drops in blood pressure on standing.", "Prolactin-pathway D2 block affects hormones. Gut 5-HT3 stimulation causes nausea. More dopamine and noradrenaline would raise blood pressure.", 3, "Explain why risperidone is started low: alpha-1 block."),
  M("ris-tremor", "risperidone", "Mr Hegde, 35, Udupi", "Risperidone was pushed up to 8 mg after a relapse. His hands now tremble and his face looks mask-like.", ["Tremor", "Mask-like face", "High dose"], "d2ns", ["5ht2c", "a1", "h1"], "At low doses risperidone's 5-HT2A block protects against stiffness, but at higher doses its tight D2 block in the movement pathway wins, and parkinsonism appears.", "5-HT2C block adds appetite. Alpha-1 block drops blood pressure on standing. H1 block sedates. None causes tremor and a mask-like face.", 3, "Recognise dose-related parkinsonism on risperidone."),
  M("ris-child", "risperidone", "Kabir, 12, Bengaluru", "Risperidone for severe irritability with autism. His mother notices his chest has grown and he is embarrassed in the school changing room.", ["Breast growth", "Boy", "Autism"], "d2ti", ["d2part", "5ht3", "nanerve"], "Risperidone raises prolactin more than most antipsychotics, and children are sensitive to this. Breast growth in boys is a sign; prolactin is checked and the dose or medicine reviewed.", "D2 partial agonism, as with aripiprazole, tends to lower prolactin. Gut 5-HT3 stimulation causes nausea. Nerve sodium channel block is how carbamazepine works.", 3, "Recognise raised prolactin in a child on risperidone."),
  M("pal-sex", "paliperidone", "Mr Fernandes, 30, Mapusa", "Stable on monthly paliperidone injections. He confides that he has no sexual desire and difficulty with erections.", ["Low desire", "Erection problems", "Monthly injection"], "d2ti", ["d2part", "5ht3", "gaba"], "Paliperidone, the active form of risperidone, also raises prolactin strongly through D2 block in the prolactin pathway, and high prolactin lowers desire and sexual function.", "D2 partial agonism would tend to lower prolactin. Gut 5-HT3 stimulation causes nausea. Paliperidone does not act at GABA-A receptors.", 2, "Link sexual problems on paliperidone to prolactin."),
  M("olz-2c", "olanzapine", "A ward pharmacist, Hyderabad", "She asks you why olanzapine and clozapine cause more weight gain than haloperidol, beyond their antihistamine effect.", ["Big weight gain", "Second reason"], "5ht2c", ["d2part", "sertplt", "ne"], "Olanzapine and clozapine block 5-HT2C receptors, removing a serotonin appetite brake in the hypothalamus. Together with H1 block this explains their high weight risk. Haloperidol does neither.", "D2 partial agonism is aripiprazole's action and is weight-neutral. The platelet pump is an SSRI action. Olanzapine does not boost noradrenaline at the heart and vessels.", 4, "Recall 5-HT2C block as the second cause of antipsychotic weight gain."),
  M("que-low", "quetiapine", "Mr Joshi, 58, Dehradun", "Prescribed quetiapine 25 mg 'just for sleep' by a GP. It knocks him out, though at this dose it hardly helps psychosis.", ["Sleepy", "Very low dose", "Used for sleep"], "h1", ["d2ns", "d2ti", "sertplt"], "At very low doses quetiapine acts mostly as an antihistamine. Its D2 block needs much higher doses. Using it for sleep still brings metabolic risks, so it is not a casual sleeping pill.", "Movement-pathway or prolactin-pathway D2 block needs much higher doses of quetiapine and would cause stiffness or hormone changes. The platelet pump explains bruising.", 3, "Explain low-dose quetiapine as an antihistamine, with its risks."),
  M("ari-gamble", "aripiprazole", "Mr Sinha, 39, Ranchi", "Since starting aripiprazole he has lost two lakh rupees on online betting apps. He never gambled before.", ["New gambling", "Can't stop", "No mania"], "d2part", ["h1", "a1", "5ht3"], "Aripiprazole partly switches on D2 and D3 receptors in the reward pathway. In some people this partial agonism drives new impulse-control problems such as gambling, shopping or binge eating. Ask about it directly.", "H1 block sedates. Alpha-1 block drops blood pressure. Gut 5-HT3 stimulation causes nausea. None drives new compulsive gambling.", 4, "Recognise impulse-control problems on aripiprazole."),
  M("amis-prl", "amisulpride", "Ms Thakur, 26, Shimla", "On amisulpride for schizophrenia. Her periods have stopped and a pregnancy test is negative.", ["No periods", "Not pregnant", "Benzamide"], "d2ti", ["5ht2c", "h1", "a1"], "Amisulpride barely crosses into the brain, so it reaches the pituitary (outside the blood-brain barrier) at high levels. Its D2 block there raises prolactin strongly.", "Amisulpride has almost no 5-HT2C, H1 or alpha-1 action, so none of these explains her missed periods.", 2, "Recognise raised prolactin on amisulpride."),
  M("lur-restless", "lurasidone", "Ms Paul, 23, Shillong", "Lurasidone was chosen for her bipolar depression because it rarely adds weight. In the first days she feels a driven restlessness and paces the room.", ["Pacing", "Restless", "Weight-friendly drug"], "d2ns", ["h1", "5ht2c", "m1"], "Akathisia is one of lurasidone's commonest side effects. It comes from D2 block in the movement pathway. Lurasidone has little H1 or 5-HT2C block, which is also why it adds little weight.", "H1 block sedates, 5-HT2C block adds appetite and muscarinic block dries the mouth; lurasidone barely does any of these.", 3, "Recognise akathisia on lurasidone."),
  M("clz-constip", "clozapine", "Mr Prakash, 33, Coimbatore", "On clozapine for treatment-resistant schizophrenia. He has not opened his bowels for five days and his belly is swollen.", ["No stools", "Swollen belly", "Clozapine"], "m1", ["5ht3", "d2ti", "sertplt"], "Clozapine blocks muscarinic receptors strongly, slowing the gut. Constipation can progress to a blocked, even fatal, bowel. Ask about bowels at every visit; this is an urgent medical review.", "Gut 5-HT3 stimulation causes nausea and loose stools rather than constipation. Clozapine barely raises prolactin. The platelet pump explains bruising.", 3, "Recognise clozapine constipation as an emergency risk."),
  M("clz-faint", "clozapine", "Ward 3, NIMHANS", "Day four of starting clozapine. Every morning he feels faint when he stands, and once he collapsed briefly in the corridor.", ["Faints on standing", "Starting dose", "Clozapine"], "a1", ["d2ti", "5ht3", "nmda"], "Clozapine is a strong alpha-1 blocker. Low blood pressure on standing is common early, which is why it is started at 12.5 mg and raised slowly, with blood pressure checked.", "Clozapine barely raises prolactin. Gut 5-HT3 stimulation causes nausea. It does not block NMDA receptors.", 2, "Explain why clozapine is raised slowly: alpha-1 block."),
  M("thx-confused", "trihexyphenidyl", "Mrs Hussain, 74, Srinagar", "Trihexyphenidyl was added to prevent stiffness. Now she forgets conversations, cannot find her room and is constipated.", ["Forgetful", "Lost in the ward", "Constipated"], "m1", ["d2ns", "gaba", "5ht3"], "Trihexyphenidyl is a pure anticholinergic. In older people, blocking muscarinic receptors impairs memory and can cause delirium. It should be reviewed and stopped if possible.", "Movement-pathway D2 block causes stiffness, which this medicine was meant to prevent. Trihexyphenidyl does not act at GABA-A receptors or on gut serotonin.", 3, "Recognise anticholinergic confusion from trihexyphenidyl in older adults."),
  M("thx-misuse", "trihexyphenidyl", "De-addiction clinic, Delhi", "A young man asks for extra trihexyphenidyl 'for my stiffness'. Friends say he takes several tablets at once to feel high.", ["Asks for more", "Takes many at once", "Feels high"], "m1", ["mufull", "5ht1a", "nmda"], "In large doses muscarinic block causes euphoria and sometimes hallucinations, so trihexyphenidyl is misused. Watch for repeated early requests, especially when there is no stiffness.", "Trihexyphenidyl has no opioid action, no 5-HT1A action and no NMDA block.", 3, "Recognise misuse of anticholinergics."),

  /* ----------------------------------------------- mood stabilisers */
  M("li-urine", "lithium", "Mr Thomas, 40, Kochi", "Ten years on lithium. He drinks five litres of water a day and gets up four times a night to pass urine.", ["Very thirsty", "Lots of urine", "Long-term lithium"], "v2block", ["adh", "h1", "m1"], "Lithium makes the kidney less responsive to the water-holding hormone (ADH). Water passes straight through, so he is thirsty and passes large amounts of urine: nephrogenic diabetes insipidus.", "Extra ADH effect would hold water back and lower sodium, the opposite. H1 block sedates. Muscarinic block would hold urine in, not pour it out.", 3, "Explain lithium's thirst and polyuria by the kidney ignoring ADH."),
  M("li-thyroid", "lithium", "Mrs Nair, 46, Thiruvananthapuram", "Lithium for bipolar disorder. She feels tired and cold, has gained weight and her TSH is high.", ["Tired", "Cold", "TSH high"], "thyroid", ["v2block", "5ht2c", "d2ti"], "Lithium slows the release of thyroid hormone from the gland. The pituitary pushes harder (TSH rises), and an underactive thyroid can follow. Thyroid tests are part of lithium monitoring; it is treated with thyroxine.", "A kidney ignoring ADH explains thirst. 5-HT2C block causes appetite and weight but not cold and a high TSH. Lithium does not block prolactin-pathway D2.", 3, "Explain lithium-induced hypothyroidism."),
  M("li-calcium", "lithium", "Mr Bhatt, 60, Vadodara", "Long-term lithium. He has a kidney stone and feels low and foggy. His calcium is high.", ["High calcium", "Kidney stone", "Long-term lithium"], "pth", ["thyroid", "v2block", "adh"], "Lithium shifts the parathyroid's calcium sensor so the glands keep making hormone at higher calcium levels. Calcium rises, with stones, low mood and fogginess. Calcium is checked in long-term lithium care.", "A slow thyroid causes tiredness and a high TSH, not high calcium. The kidney ignoring ADH causes thirst. Extra ADH lowers sodium.", 4, "Recognise lithium-related high calcium."),
  M("vpa-ammonia", "valproate", "Ms Rizvi, 28, Lucknow", "On valproate for mania. She is drowsy, slowed and confused. Her liver tests and valproate level are normal, but her blood ammonia is high.", ["Drowsy and confused", "Normal level", "Ammonia high"], "ammonia", ["herg", "thyroid", "mt1"], "Valproate can slow the urea cycle, the liver's way of clearing ammonia, so ammonia builds up and clouds the brain even when the valproate level and liver tests are normal. Confusion on valproate needs an ammonia check.", "Potassium channel block lengthens QT. A slow thyroid causes tiredness with a high TSH. Valproate has no melatonin action.", 4, "Recognise valproate-related high ammonia."),
  M("cbz-na", "carbamazepine", "Mrs D'Silva, 70, Pune", "Carbamazepine for bipolar disorder. She has a headache, feels sick and is confused. Her sodium is 126.", ["Low sodium", "Confused", "Older adult"], "adh", ["v2block", "nanerve", "h1"], "Carbamazepine increases the effect of the water-holding hormone (ADH), so the body keeps water and sodium is diluted. Older people and those on water tablets are most at risk.", "A kidney ignoring ADH is lithium's effect and pushes sodium up. Nerve sodium channel block is how carbamazepine works, but it is not why blood sodium falls. H1 block sedates.", 4, "Tell carbamazepine's low sodium apart from its mechanism."),
  M("cbz-double", "carbamazepine", "Mr Ali, 45, Bhopal", "Carbamazepine went up to 1200 mg. He now sees double, walks as if drunk and feels sick.", ["Double vision", "Unsteady", "Dose went up"], "nanerve", ["adh", "d2ns", "m1"], "Carbamazepine blocks sodium channels in nerves. Too much block in the balance and eye-movement systems causes double vision and unsteadiness, classic signs of a level that is too high.", "Extra ADH effect causes low sodium and confusion rather than double vision. Carbamazepine has no D2 block. Muscarinic block causes blur, not double vision with unsteadiness.", 3, "Recognise carbamazepine toxicity signs."),
  M("oxc-na", "oxcarbazepine", "Mr Kamath, 66, Karwar", "Switched from carbamazepine to oxcarbazepine to avoid interactions. His sodium has dropped to 128.", ["Low sodium", "Switch from carbamazepine"], "adh", ["nanerve", "5ht3", "ne"], "Oxcarbazepine causes low sodium even more often than carbamazepine, through a similar effect on water handling. Sodium is checked early and when there is confusion.", "Nerve sodium channel block is its anticonvulsant action, not why blood sodium falls. Gut 5-HT3 causes nausea. Oxcarbazepine does not boost noradrenaline.", 2, "Recall that oxcarbazepine lowers sodium often."),
  M("ltg-dizzy", "lamotrigine", "Ms Pandey, 32, Prayagraj", "Lamotrigine went up to 200 mg. She is dizzy, sees double when tired and is a little unsteady.", ["Dizzy", "Double vision", "Higher dose"], "nanerve", ["h1", "a1", "adh"], "Lamotrigine blocks nerve sodium channels. Too much block in the balance and eye-movement systems causes dizziness and double vision, usually dose-related.", "Lamotrigine has no H1 or alpha-1 block, which would cause sleepiness or dizziness on standing. It does not lower sodium the way carbamazepine does.", 3, "Recognise dose-related dizziness on lamotrigine."),

  /* ---------------------------------------------- anxiety and sleep */
  M("lor-recall", "lorazepam", "Mr Malhotra, 51, Delhi", "Given lorazepam before an MRI because he is claustrophobic. Afterwards he cannot remember the scan or the drive home.", ["No memory", "Of the procedure", "Single dose"], "gaba", ["m1", "h1", "nmda"], "Benzodiazepines boost GABA-A, the brain's main calming signal. In the memory circuits this blocks new memories from forming after the dose (anterograde amnesia).", "Muscarinic block can also cloud memory, but lorazepam does not block muscarinic receptors. It has no H1 or NMDA action.", 2, "Explain anterograde amnesia after a benzodiazepine."),
  M("clon-falls", "clonazepam", "Mrs Agarwal, 79, Kolkata", "Clonazepam 0.5 mg twice daily 'for nerves' for years. She has fallen twice this month and walks unsteadily.", ["Falls", "Unsteady", "Long-acting benzodiazepine"], "gaba", ["a1", "nanerve", "d2ns"], "Boosting GABA-A in the cerebellum and brainstem slows reactions and balance. Long-acting benzodiazepines build up in older people, so falls and hip fractures follow. A slow taper is often the kind choice.", "Alpha-1 block also causes falls, but through blood pressure, and clonazepam has no alpha-1 action. Nerve sodium channel block causes double vision on anticonvulsants. Clonazepam has no D2 block.", 4, "Tell benzodiazepine falls apart from blood-pressure falls."),
  M("zol-night", "zolpidem", "Ms Sethi, 45, Noida", "On zolpidem for insomnia. Her husband found her cooking at 2 am. In the morning she remembered nothing.", ["Night cooking", "No memory", "Sleeping pill"], "gaba", ["mt1", "h1", "5ht2"], "Zolpidem acts at the GABA-A receptor (the alpha-1 type) like a selective benzodiazepine. It can cause complex sleep behaviours such as eating, cooking or driving while not fully awake, with no memory later. It should be stopped if this happens.", "Melatonin receptor stimulation gently shifts sleep timing and does not cause sleep-cooking. Zolpidem has no H1 or 5-HT2 action.", 3, "Recognise complex sleep behaviours on zolpidem."),
  M("mel-jetlag", "melatonin", "Dr Kapoor, 50, flying Delhi to Toronto", "He takes melatonin in the evening at his destination. Within a few days his sleep fits the new time zone.", ["Jet lag", "Evening dose", "Sleep shifts"], "mt1", ["gaba", "h1", "a2d"], "Melatonin acts on MT1 and MT2 receptors in the body clock, signalling 'night'. Timed well, it shifts sleep rather than sedating strongly.", "Melatonin does not boost GABA-A, block H1 or bind the calcium channel subunit; those would sedate whatever the clock time.", 1, "Recognise melatonin's body-clock action."),
  M("mel-child", "melatonin", "Aarohi, 7, Ahmedabad", "Autism and very late sleep onset. A low dose of melatonin before bed helps her fall asleep an hour earlier, with no grogginess.", ["Child", "Late sleep onset", "No grogginess"], "mt1", ["h1", "gaba", "m1"], "Melatonin signals night to the body clock. In children with autism, poor melatonin rhythms often delay sleep, and a small dose helps, alongside a steady bedtime routine.", "H1 block and GABA-A boosting sedate and can leave grogginess. Muscarinic block dries and confuses. Melatonin does none of these.", 2, "Recall melatonin's use for sleep onset in children."),
  M("pro-litremor", "propranolol", "Mr Banerjee, 52, Asansol", "Lithium gives him a fine tremor that ruins his handwriting. Propranolol 10 mg twice daily steadies his hand.", ["Tremor eased", "On lithium", "Small dose"], "beta", ["gaba", "a1", "m1"], "Fine tremor is driven partly by adrenaline acting on beta receptors in muscle. Propranolol blocks them and reduces the tremor. It is used for lithium tremor and for antipsychotic-induced restlessness.", "Propranolol has no GABA-A action. Alpha-1 block lowers blood pressure but does not steady tremor. Muscarinic block treats stiffness, not this tremor.", 2, "Explain propranolol's use for tremor."),
  M("pro-wheeze", "propranolol", "Ms Rao, 22, Hyderabad", "She took her friend's propranolol before a viva. Within an hour she was wheezing; she has had asthma since childhood.", ["Wheeze", "Asthma", "Borrowed tablet"], "beta", ["h1", "a1", "m1"], "Airways are kept open by adrenaline at beta-2 receptors. Propranolol blocks beta-1 and beta-2, so in asthma it can trigger a serious attack. It must not be used in asthma.", "H1 block is anti-allergic and does not tighten airways. Alpha-1 block lowers blood pressure. Muscarinic block opens the airways, the opposite.", 3, "Recognise propranolol's danger in asthma."),
  M("pro-viva", "propranolol", "Mr Krishnan, 25, Chennai", "Before his clinical exam his voice shakes and his heart races. A small dose of propranolol an hour before keeps him steady; his worry is still there.", ["Shaking", "Racing heart", "Worry unchanged"], "beta", ["gaba", "5ht1a", "h1"], "Performance anxiety's body signs (tremor, racing heart) come from adrenaline at beta receptors. Propranolol blocks these but does not touch the worry itself, which is why it suits one-off performance situations.", "A GABA-A boost would calm the mind and sedate. Serotonin 1A partial agonism takes a long time to work. H1 block sedates.", 1, "Recognise propranolol for the body signs of performance anxiety."),
  M("pro-akathisia", "propranolol", "Mr Shetty, 40, Mangaluru", "Restless legs and pacing on aripiprazole. Low-dose propranolol eases the restlessness within days.", ["Restlessness eased", "On aripiprazole"], "beta", ["5ht3", "mt1", "adh"], "Akathisia is relieved in many people by blocking beta receptors with low-dose propranolol, a common first step alongside lowering the antipsychotic dose.", "Gut 5-HT3 stimulation causes nausea. Melatonin receptors shift sleep timing. Extra ADH effect lowers sodium. None of these relieves restlessness.", 3, "Recall propranolol as a treatment for akathisia."),
  M("bus-nodep", "buspirone", "Mrs Arora, 63, Faridabad", "Her doctor chose buspirone for worry because she fears 'getting hooked'. It does not make her sleepy, but it took a long time to help.", ["Not sleepy", "No dependence", "Slow to work"], "5ht1a", ["gaba", "h1", "a2d"], "Buspirone partly stimulates serotonin 1A receptors. It does not touch GABA-A, so there is no sedation, no dependence and no withdrawal, but benefit builds slowly.", "A GABA-A boost is the benzodiazepine action, which brings sedation and dependence. H1 block sedates. Alpha-2-delta binding is pregabalin's action, which can be misused.", 3, "Explain why buspirone is not sedating or habit-forming."),
  M("pgb-misuse", "pregabalin", "De-addiction OPD, Amritsar", "A man asks for more pregabalin. He takes 1200 mg a day 'to feel relaxed and floaty', often with heroin.", ["High dose", "Euphoria", "With opioids"], "a2d", ["mufull", "gaba", "dane"], "Pregabalin binds the alpha-2-delta part of calcium channels and reduces excitatory signalling. At high doses it gives a relaxed high and is misused, especially with opioids, where it adds to dangerous slowing of breathing.", "Pregabalin is not an opioid and does not act at GABA-A receptors directly. It does not raise dopamine and noradrenaline like a stimulant.", 4, "Recognise pregabalin misuse and its risk with opioids."),
  M("pgb-swelling", "pregabalin", "Mrs Khanna, 57, Delhi", "Pregabalin for anxiety and nerve pain. She feels dizzy, has put on weight and her ankles are puffy by evening.", ["Dizzy", "Weight gain", "Swollen ankles"], "a2d", ["h1", "a1", "5ht2c"], "These are typical effects of alpha-2-delta binding: dizziness, sleepiness, weight gain and fluid in the legs. They are dose-related.", "Pregabalin has no H1, alpha-1 or 5-HT2C action. Each of those can cause sleepiness, dizziness or weight, but none is how pregabalin works.", 2, "Recognise pregabalin's common side effects."),
  M("lor-paradox", "lorazepam", "Mr Gupta, 84, Meerut", "Given lorazepam for night-time agitation on a medical ward. He became louder, disinhibited and tried to climb over the bed rails.", ["More agitated", "Disinhibited", "Very old"], "gaba", ["dane", "5ht2", "ne"], "Boosting GABA-A in the frontal lobes can remove social brakes before it sedates, especially in the very old, children and people with brain injury. This paradoxical reaction is another reason to avoid benzodiazepines in delirium.", "Lorazepam does not raise dopamine, noradrenaline or serotonin, so none of those explains this.", 3, "Recognise paradoxical disinhibition on a benzodiazepine."),
  M("chl-shakes", "chlordiazepoxide", "Mr Reddy, 48, Nizamabad", "Admitted for alcohol detox. A reducing course of chlordiazepoxide calms his shakes and sweating, and no fits happen.", ["Shakes settle", "No fits", "Alcohol detox"], "gaba", ["mublock", "aldh", "nmda"], "Alcohol boosts GABA-A. After heavy drinking stops, the brain is left over-excited. A benzodiazepine fills in at the same GABA-A receptor (cross-tolerance), then is tapered off.", "Opioid receptor block is naltrexone's action and does not treat withdrawal. Aldehyde enzyme block is disulfiram's, which is dangerous during drinking. Chlordiazepoxide does not block NMDA receptors.", 2, "Explain benzodiazepines in alcohol withdrawal."),
  M("alp-tolerance", "alprazolam", "Ms Iyer, 35, Bengaluru", "Alprazolam every day for two years. She now needs three tablets for the calm one used to give, and feels shaky if a dose is late.", ["Needs more", "Shaky between doses", "Daily use"], "gaba", ["mufull", "5ht1a", "h1"], "With daily use, GABA-A receptors adapt and become less responsive. More drug is needed for the same effect (tolerance), and missing doses causes withdrawal. Short-acting benzodiazepines show this most.", "Alprazolam is not an opioid and has no 5-HT1A or H1 action.", 3, "Explain benzodiazepine tolerance and withdrawal."),

  /* --------------------------------------------- ADHD and dementia */
  M("atx-pulse", "atomoxetine", "Rhea, 14, Kolkata", "Atomoxetine for ADHD. At review her pulse is 106 and her blood pressure a little higher than before.", ["Pulse up", "Blood pressure up", "Non-stimulant"], "ne", ["ach", "h1", "5ht3block"], "Atomoxetine blocks the noradrenaline pump. More noradrenaline at the heart and vessels raises pulse and blood pressure, which are checked before and during treatment.", "Extra acetylcholine slows the pulse. H1 block sedates. 5-HT3 block eases sickness. None raises pulse and blood pressure.", 2, "Recognise atomoxetine's effect on pulse and blood pressure."),
  M("mph-snort", "methylphenidate", "Student counselling, Kota", "A coaching student crushes and snorts his friend's methylphenidate to study through the night before tests.", ["Crushed and snorted", "Stays awake", "Not prescribed"], "dane", ["mufull", "gaba", "5ht1a"], "Methylphenidate blocks the dopamine and noradrenaline pumps. Snorting brings a fast rise in dopamine, which is what makes it misusable, and it adds risks to the heart.", "Methylphenidate is not an opioid, does not boost GABA-A and has no 5-HT1A action.", 3, "Recognise stimulant misuse and why it happens."),
  M("mph-bp", "methylphenidate", "Mr Varma, 32, Visakhapatnam", "Adult ADHD diagnosed last year. On methylphenidate his blood pressure is 142/92 and his heart races in the afternoon.", ["Blood pressure up", "Racing heart", "Adult"], "dane", ["a1", "h1", "ach"], "More noradrenaline from methylphenidate tightens vessels and speeds the heart. Pulse and blood pressure are checked before starting and on every dose change.", "Alpha-1 block lowers blood pressure. H1 block sedates. Extra acetylcholine slows the heart. None of them raises it.", 2, "Recall cardiovascular checks for stimulants."),
  M("don-gut", "donepezil", "Mrs Menon, 77, Kochi", "Started donepezil for Alzheimer's disease. For the first days she feels sick, has loose stools and has lost her appetite.", ["Nausea", "Loose stools", "Dementia medicine"], "achgut", ["5ht3", "m1", "d2ctz"], "Donepezil stops acetylcholine being broken down everywhere, including the gut, where it speeds things up: nausea, diarrhoea and poor appetite. Starting low and going up slowly helps.", "Donepezil does not raise serotonin. Muscarinic block would constipate, the opposite. Blocking D2 in the vomiting centre eases sickness rather than causing it.", 2, "Explain donepezil's gut side effects."),
  M("mem-dizzy", "memantine", "Mr Sharma, 80, Haridwar", "Memantine was added for moderate Alzheimer's disease. He feels dizzy and a little more confused for the first few days.", ["Dizzy", "More confused", "Dementia medicine"], "nmda", ["ach", "achgut", "h1"], "Memantine blocks NMDA glutamate receptors when they are overactive. Early on this can cause dizziness, headache and confusion, which usually settle; the dose is built up slowly.", "Extra acetylcholine at the heart or gut is how donepezil causes a slow pulse or loose stools. Memantine has no H1 block.", 2, "Recognise memantine's early side effects."),

  /* --------------------------------------------- alcohol and drugs */
  M("bpn-precip", "buprenorphine", "Opioid clinic, Imphal", "He used heroin six hours ago. Minutes after his first buprenorphine tablet he is sweating, yawning, crampy and furious: 'You made it worse!'", ["Worse after first dose", "Heroin recently", "Withdrawal signs"], "mupart", ["mufull", "aldh", "nmda"], "Buprenorphine grips the mu receptor tightly but switches it on only partly. Given while heroin is still on the receptors, it pushes heroin off and replaces a full signal with a partial one, so withdrawal suddenly appears. The first dose waits for clear withdrawal signs.", "A full mu agonist would ease withdrawal, not cause it. Aldehyde enzyme block is disulfiram's reaction with alcohol. Buprenorphine does not block NMDA.", 4, "Explain precipitated withdrawal with buprenorphine."),
  M("bpn-ceiling", "buprenorphine", "Harm-reduction outreach, Aizawl", "A peer worker explains why buprenorphine maintenance is safer in overdose than heroin, as long as it is not mixed with sedatives.", ["Safer in overdose", "Unless mixed"], "mupart", ["mufull", "gaba", "nmda"], "As a partial agonist, buprenorphine's effect on breathing levels off at higher doses (a ceiling). Full agonists like heroin keep slowing breathing as the dose rises. Mixing with benzodiazepines or alcohol removes much of this safety.", "A full mu agonist has no ceiling, which is the danger of heroin. Buprenorphine has no GABA-A or NMDA action.", 3, "Explain buprenorphine's ceiling effect and its limit."),
  M("bpn-constip", "buprenorphine", "Mr Lalremruata, 36, Aizawl", "Stable on buprenorphine. His pupils are small and he has been constipated since he started.", ["Small pupils", "Constipated", "Maintenance"], "mupart", ["mublock", "achgut", "aldh"], "Even partial mu activation slows the gut and narrows the pupils, like other opioids, though less strongly.", "Opioid receptor block would cause withdrawal-type loose stools and wide pupils, the opposite. More acetylcholine in the gut speeds it up. Aldehyde enzyme block is disulfiram's action.", 2, "Recognise opioid effects on buprenorphine."),
  M("bpn-inject", "buprenorphine", "Needle exchange, Manipur", "He crushed and injected Addnok-N tablets hoping for a high. Instead he felt sudden, intense withdrawal.", ["Injected a combination tablet", "Sudden withdrawal"], "mublock", ["aldh", "gaba", "nmda"], "Addnok-N combines buprenorphine with naloxone. Swallowed under the tongue, naloxone is barely absorbed. Injected, naloxone blocks opioid receptors at full strength and triggers withdrawal, which is the point of the combination.", "Aldehyde enzyme block causes the disulfiram reaction. Neither medicine boosts GABA-A or blocks NMDA.", 4, "Explain why the naloxone combination discourages injecting."),
  M("nal-precip", "naltrexone", "Rehab centre, Ludhiana", "He said he had been opioid-free for a long time, so naltrexone was started. Within the hour: goosebumps, vomiting, cramps and a runny nose.", ["Withdrawal after first dose", "Recent opioid use hidden"], "mublock", ["mupart", "aldh", "nmda"], "Naltrexone blocks opioid receptors completely. If opioids are still being used, it throws them off the receptors and causes sudden withdrawal. A urine test and an opioid-free gap come first.", "Partial agonism is buprenorphine's action. Aldehyde enzyme block is disulfiram's. Naltrexone does not block NMDA.", 4, "Recognise precipitated withdrawal with naltrexone."),
  M("nal-drink", "naltrexone", "Mr Kohli, 50, Delhi", "On naltrexone for alcohol dependence. 'I had two drinks at a wedding but it felt pointless, so I stopped.'", ["Drinking less rewarding", "Stopped after two"], "mublock", ["aldh", "nmda", "gaba"], "Part of alcohol's reward comes through the brain's own opioids. Blocking opioid receptors takes the pleasure out, so people drink less. There is no reaction with alcohol.", "Aldehyde enzyme block is disulfiram, which would have made him flushed and sick. Naltrexone does not block NMDA or boost GABA-A.", 4, "Tell naltrexone (less reward) from disulfiram (a reaction)."),
  M("dis-sauce", "disulfiram", "Mr Naidu, 46, Tirupati", "On disulfiram. After a restaurant dinner cooked in wine sauce, he became flushed with a pounding headache and vomited.", ["Flushed", "Headache", "After a meal"], "aldh", ["mublock", "nmda", "h1"], "Disulfiram blocks aldehyde dehydrogenase, so even small amounts of alcohol in food make acetaldehyde pile up, causing flushing, headache, racing heart and vomiting.", "Opioid receptor block is naltrexone's action and does not cause a reaction. Disulfiram does not block NMDA or H1.", 2, "Recognise the disulfiram reaction from hidden alcohol in food."),
];
